it("posting rule competing parent retarget waits for valid insertion then rejects atomically",async()=>{
  const rule=await mockPrisma.financePostingRule.create({data:{legalEntityId:entity().id,code:randomUUID(),name:"Synthetic lock",sourceType:"payment",eventType:"synthetic"}}),before=await ruleRecords();
  const child=await pool.connect(),parent=await pool.connect();let lineId:string|undefined;
  try{await child.query("BEGIN");await parent.query("BEGIN");lineId=(await child.query('INSERT INTO "FinancePostingRuleLine" ("postingRuleId","legalEntityId","lineNumber",side,"accountId","updatedAt") VALUES ($1,$2,1,$3,$4,NOW()) RETURNING id',[rule.id,entity().id,"debit",accounts.get(owned.companyId)])).rows[0].id;
    await parent.query('INSERT INTO "FinanceAuditEvent" ("legalEntityId",action) VALUES ($1,$2)',[entity().id,"synthetic-rule-race"]);
    await parent.query('INSERT INTO "FinanceDomainEventOutbox" ("legalEntityId","aggregateType","aggregateId","eventType","occurredAt","payloadJson","updatedAt") VALUES ($1,$2,$3,$4,NOW(),$5,NOW())',[entity().id,"synthetic-rule",rule.id,"synthetic.race",{}]);
    const pid=(await parent.query('SELECT pg_backend_pid() AS pid')).rows[0].pid;
    const pending=parent.query('UPDATE "FinancePostingRule" SET "legalEntityId"=$1 WHERE id=$2',[entity(ids.organizations.transAsiaDe).id,rule.id]).then(()=>({accepted:true}),error=>({error}));
    let blocked=false;for(let i=0;i<40;i++){const activity:any[]=await mockPrisma.$queryRaw`SELECT wait_event_type FROM pg_stat_activity WHERE pid = ${pid}`;if(activity[0]?.wait_event_type==="Lock"){blocked=true;break;}await new Promise(resolve=>setTimeout(resolve,25));}expect(blocked).toBe(true);await child.query("COMMIT");const result:any=await pending;expect(result.error?.code).toBe("23503");expect(result.error?.constraint).toBe("FinancePostingRuleLine_rule_entity_fkey");await parent.query("ROLLBACK");
    expect((await mockPrisma.financePostingRule.findUniqueOrThrow({where:{id:rule.id}})).legalEntityId).toBe(entity().id);
    await mockPrisma.financePostingRuleLine.update({where:{id:lineId},data:{lineNumber:2}});
  }finally{await child.query("ROLLBACK");await parent.query("ROLLBACK");child.release();parent.release();if(lineId)await mockPrisma.financePostingRuleLine.delete({where:{id:lineId}});}
  expect(await ruleRecords()).toEqual(before);await mockPrisma.financePostingRule.delete({where:{id:rule.id}});
});

