it("payment run compound parent retarget waits for a valid child then rejects with audit/outbox rollback",async()=>{
 const template=await mockPrisma.financePaymentRun.findUniqueOrThrow({where:{id:runs.get(owned.companyId)![0]}}),run=await mockPrisma.financePaymentRun.create({data:{legalEntityId:entity().id,bankAccountId:template.bankAccountId,runNumber:randomUUID(),paymentDate:template.paymentDate,currency:template.currency,totalAmount:template.totalAmount,fxRate:template.fxRate,idempotencyKey:randomUUID(),payloadHash:"synthetic",createdByUserId:owned.userId}}),before=await runRecords(),child=await pool.connect(),parent=await pool.connect();let lineId:string|undefined;
 try{await child.query("BEGIN");await parent.query("BEGIN");lineId=(await child.query('INSERT INTO "FinancePaymentRunLine" ("legalEntityId","paymentRunId",sequence,"payableItemId","carrierProviderId","carrierCode",amount,"updatedAt") VALUES ($1,$2,1,$3,$4,$5,$6,NOW()) RETURNING id',[entity().id,run.id,runPayables.get(owned.companyId)![0],randomUUID(),"SYN","0.1000"])).rows[0].id;
 await parent.query('INSERT INTO "FinanceAuditEvent" ("legalEntityId",action) VALUES ($1,$2)',[entity().id,"synthetic-payment-race"]);await parent.query('INSERT INTO "FinanceDomainEventOutbox" ("legalEntityId","aggregateType","aggregateId","eventType","occurredAt","payloadJson","updatedAt") VALUES ($1,$2,$3,$4,NOW(),$5,NOW())',[entity().id,"synthetic-run",run.id,"synthetic.race",{}]);const pid=(await parent.query('SELECT pg_backend_pid() AS pid')).rows[0].pid;
 const pending=parent.query('UPDATE "FinancePaymentRun" SET "legalEntityId"=$1,"bankAccountId"=$2 WHERE id=$3',[entity(ids.organizations.transAsiaDe).id,runBanks.get(ids.organizations.transAsiaDe),run.id]).then(()=>({accepted:true}),error=>({error}));let blocked=false;for(let i=0;i<40;i++){const activity:any[]=await mockPrisma.$queryRaw`SELECT wait_event_type FROM pg_stat_activity WHERE pid = ${pid}`;if(activity[0]?.wait_event_type==="Lock"){blocked=true;break;}await new Promise(resolve=>setTimeout(resolve,25));}expect(blocked).toBe(true);await child.query("COMMIT");const result:any=await pending;expect(result.error?.code).toBe("23503");expect(result.error?.constraint).toBe("FinancePaymentRunLine_run_entity_fkey");await parent.query("ROLLBACK");
 }finally{await child.query("ROLLBACK");await parent.query("ROLLBACK");child.release();parent.release();if(lineId)await mockPrisma.financePaymentRunLine.delete({where:{id:lineId}});}expect(await runRecords()).toEqual(before);await mockPrisma.financePaymentRun.delete({where:{id:run.id}});
});

