it("provider header integrity rejects foreign company/provider/entity inserts and updates atomically",async()=>{
 for(const [table,map,providerField,configs,snapshot] of [
  ["FinanceProviderSettlement",providerSettlements,"providerConfigId",settlementConfigs,settlementRecords],
  ["FinanceCarrierBill",carrierBills,"carrierProviderId",billProviders,billRecords]
 ] as const){
  const id=map.get(owned.companyId)![0],before=await snapshot();
  for(const company of [ids.organizations.transAsiaDe,ids.organizations.unrelated]){
   const entity=fixture.financeLegalEntities.find(e=>e.companyId===company)!;
   for(const [field,value,constraint] of [[providerField,configs.get(company)!,table+"_provider_company_fkey"],["legalEntityId",entity.id,table+"_entity_company_fkey"]]){
    await rejected('UPDATE "'+table+'" SET "'+field+'"=$2 WHERE id=$1',[id,value],constraint);
    // Duplicate the complete valid header with a fresh durable identity and one invalid reference.
    const columns=(await pool.query('SELECT column_name FROM information_schema.columns WHERE table_schema=\'public\' AND table_name=$1 ORDER BY ordinal_position',[table])).rows.map((r:any)=>r.column_name);
    const select=columns.map((c:string)=>c==="id"?'$2::uuid':c===field?'$3::uuid':c==="idempotencyKey"||c==="settlementNumber"||c==="billNumber"||c==="supplierInvoiceNumber"?'$2::text':'"'+c+'"').join(',');
    await rejected('INSERT INTO "'+table+'" ('+columns.map((c:string)=>'"'+c+'"').join(',')+') SELECT '+select+' FROM "'+table+'" WHERE id=$1',[id,randomUUID(),value],constraint);
   }
  }
  await rejected('UPDATE "'+table+'" SET "companyId"=NULL WHERE id=$1',[id],table+"_company_required_check","23514");
  await rejected('UPDATE "'+table+'" SET "'+providerField+'"=$2 WHERE id=$1',[id,randomUUID()],table+"_provider_company_fkey");
  expect(await snapshot()).toEqual(before);
 }
 const catalog=await pool.query('SELECT conname,convalidated FROM pg_constraint WHERE conname = ANY($1)',[["FinanceProviderSettlement_entity_company_fkey","FinanceProviderSettlement_provider_company_fkey","FinanceCarrierBill_entity_company_fkey","FinanceCarrierBill_provider_company_fkey","FinanceProviderSettlement_company_required_check","FinanceCarrierBill_company_required_check"]]);
 expect(catalog.rows).toHaveLength(6);expect(catalog.rows.every((r:any)=>r.convalidated===false)).toBe(true);
});

it("provider header integrity concurrent referenced-provider retarget waits for key-share holder then rolls back",async()=>{
 for(const [table,providers,providerTable,semanticField,semanticValue,snapshot] of [
  ["FinanceProviderSettlement",settlementConfigs,"PaymentProviderConfig","environment","PRODUCTION",settlementRecords],
  ["FinanceCarrierBill",billProviders,"IntegrationProvider","providerCode","SYN-RACE",billRecords]
 ] as const){
  const provider=providers.get(owned.companyId)!,before=await snapshot(),child=await pool.connect(),parent=await pool.connect();
  try{
   await child.query("BEGIN");await parent.query("BEGIN");
   // PostgreSQL FK validation acquires the referenced tuple's key-share lock.
   await child.query('SELECT id FROM "'+providerTable+'" WHERE id=$1 FOR KEY SHARE',[provider]);
   await parent.query('INSERT INTO "FinanceAuditEvent" ("legalEntityId",action) VALUES ($1,$2)',[entity().id,"synthetic-provider-race"]);
   await parent.query('INSERT INTO "FinanceDomainEventOutbox" ("legalEntityId","aggregateType","aggregateId","eventType","occurredAt","payloadJson","updatedAt") VALUES ($1,$2,$3,$4,NOW(),$5,NOW())',[entity().id,"synthetic-provider",provider,"synthetic.competing",{}]);
   const pid=(await parent.query('SELECT pg_backend_pid() AS pid')).rows[0].pid;
   const pending=parent.query('UPDATE "'+providerTable+'" SET "companyId"=$1,"'+semanticField+'"=$2 WHERE id=$3',[ids.organizations.unrelated,semanticValue,provider]).then(()=>({accepted:true}),error=>({error}));
   let blocked=false;for(let i=0;i<40;i++){const rows:any[]=await mockPrisma.$queryRaw`SELECT wait_event_type FROM pg_stat_activity WHERE pid = ${pid}`;if(rows[0]?.wait_event_type==="Lock"){blocked=true;break;}await new Promise(resolve=>setTimeout(resolve,25));}
   expect(blocked).toBe(true);await child.query("COMMIT");const result:any=await pending;
   expect(result.error?.code).toBe("23503");expect(result.error?.constraint).toBe(table+"_provider_company_fkey");await parent.query("ROLLBACK");
  }finally{await child.query("ROLLBACK");await parent.query("ROLLBACK");child.release();parent.release();}
  expect(await snapshot()).toEqual(before);
 }
});

